<script setup lang="ts">import {ref} from 'vue';import {post} from '../api/client';import {save} from '../stores/session';import type {User} from '../types/domain';import Notice from '../components/common/Notice.vue';const emit=defineEmits<{login:[User]}>();const email=ref('analyst@yanzhou.demo'),password=ref('Route2026!'),error=ref(''),busy=ref(false);async function login(){busy.value=true;try{const r=await post<{token:string;user:User}>('/auth/login',{email:email.value,password:password.value});save(r.token,r.user);emit('login',r.user)}catch(e){error.value=(e as Error).message}finally{busy.value=false}};</script><template><main class="login"><section class="login-logbook"><span class="logbook-label">YANZHOU / ALTERNATIVE PASSAGES</span><h1>几条备选航段，<br/>如何说清权衡？</h1><p>先核查指标方向与权重判断，<br/>再看理想点距离和名次的敏感性。</p><div class="cover-columns"><span>01<small>指标方向</small></span><span>02<small>判断一致性</small></span><span>03<small>扰动复核</small></span></div><small>模拟方案讨论 / 不提供实际导航指令</small></section><section class="login-form"><span class="eyebrow">岩舟航运 · 多指标比较航册</span><h2>打开权衡航册</h2><p>方案、权重与复核依据一并留存。</p><form @submit.prevent="login"><label>工作账号<input aria-label="工作账号" v-model="email"/></label><label>密码<input aria-label="密码" type="password" v-model="password"/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">{{busy?'正在验证…':'打开航册　→'}}</button></form><div class="login-accounts"><b>演示账号</b><p>admin / analyst / viewer @yanzhou.demo<br/>统一密码 Route2026!</p></div></section></main></template>
